'use strict';

/**
 * Order timeline (FR2). Shared by every service that writes timeline events (orders, files) and by
 * readers of an order's latest activity (dashboard). Import as require('common/timeline').
 *
 * Entries table (owned by the timeline service): PK orderId, SK id, LSI byTime (orderId, timeKey).
 * Reads process.env.TIMELINE_TABLE at call time only, never at load time, so any service can load
 * this module without that variable.
 */

const crypto = require('crypto');
const { QueryCommand } = require('@aws-sdk/lib-dynamodb');
const { doc } = require('../database');

const BY_TIME = 'byTime';

const EVENT_TYPES = Object.freeze([
    'STATUS_CHANGED',
    'ASSIGNED',
    'UNASSIGNED',
    'PRIMARY_CHANGED',
    'FILE_ADDED',
    'FILE_REMOVED',
]);

/** Sort key of the byTime index: ISO time, then the entry id to order entries with the same time. */
function timeKey(createdAt, id) {
    return `${createdAt}#${id}`;
}

/**
 * Builds an Entries EVENT item. `user` is the acting user ({ userId, name }); the name is a snapshot.
 * `at` is the ISO time of the change (use the same value as the write it belongs to).
 */
function buildEvent({ orderId, type, user, details, at }) {
    if (!EVENT_TYPES.includes(type)) throw new Error(`timeline: unknown event type ${type}`);
    const id = crypto.randomUUID();
    const createdAt = at || new Date().toISOString();
    return {
        orderId,
        id,
        kind: 'EVENT',
        type,
        createdAt,
        timeKey: timeKey(createdAt, id),
        actorUserId: user.userId,
        actorName: user.name,
        details: details || {},
    };
}

/** A TransactWriteItems entry that puts the event item (never overwrites an existing entry). */
function eventPut(item) {
    return {
        Put: {
            TableName: process.env.TIMELINE_TABLE,
            Item: item,
            ConditionExpression: 'attribute_not_exists(id)',
        },
    };
}

/** ISO time of the order's newest timeline entry, or null when the order has none. */
async function latestActivityAt(orderId) {
    const res = await doc.send(
        new QueryCommand({
            TableName: process.env.TIMELINE_TABLE,
            IndexName: BY_TIME,
            KeyConditionExpression: '#orderId = :orderId',
            ExpressionAttributeNames: { '#orderId': 'orderId', '#createdAt': 'createdAt' },
            ExpressionAttributeValues: { ':orderId': orderId },
            ProjectionExpression: '#createdAt',
            ScanIndexForward: false,
            Limit: 1,
        })
    );
    const item = res.Items && res.Items[0];
    return item ? item.createdAt : null;
}

module.exports = { EVENT_TYPES, BY_TIME, timeKey, buildEvent, eventPut, latestActivityAt };
